<?php
namespace App\Http\Controllers\Api\Admin; use App\Http\Controllers\Controller; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class LogisticsReportController extends Controller { public function index(Request$r):JsonResponse{$this->view($r);$f=$r->validate(['type'=>['nullable','string','max:40'],'status'=>['nullable','string','max:30'],'search'=>['nullable','string','max:150'],'per_page'=>['nullable','integer','between:1,100']]);$q=DB::table('report_runs as rr')->join('report_definitions as rd','rd.id','=','rr.report_definition_id')->leftJoin('users as u','u.id','=','rr.user_id')->whereNull('rd.deleted_at')->where('rd.report_type','logistics');if(!empty($f['type']))$q->where('rr.report_type',$f['type']);if(!empty($f['status']))$q->where('rr.status',$f['status']);if(!empty($f['search'])){$s='%'.$f['search'].'%';$q->where(fn($x)=>$x->where('rd.name','like',$s)->orWhere('rr.uuid','like',$s));}$rows=(clone$q)->select('rr.*','rd.name as definition_name','u.name as owner_name')->latest('rr.created_at')->paginate($f['per_page']??25);$total=(clone$q)->count();$audit=DB::table('activity_log')->where(fn($x)=>$x->where('description','like','logistics_report.%')->orWhere('description','like','logistics_%'))->count();return response()->json(['data'=>['operations'=>$rows,'intelligence'=>['healthScore'=>0,'healthTrendText'=>'—','governanceScorecards'=>[],'recentReconciliationSummary'=>[],'quickQueues'=>['exportsQueue'=>(clone$q)->where('rr.status','queued')->count(),'claimsQueue'=>0,'reconciliationQueue'=>DB::table('logistics_reconciliation_runs')->where('status','<>','completed')->count(),'recoveriesQueue'=>0]],'metrics'=>['total'=>$total,'completed'=>(clone$q)->where('rr.status','completed')->count(),'failed'=>(clone$q)->where('rr.status','failed')->count(),'auditEvents'=>$audit]]]);} public function store(Request$r):JsonResponse{$this->create($r);$d=$r->validate(['operation_type'=>['required',Rule::in(['Import','Export','Report','Audit','Reconciliation'])],'name'=>['required','string','max:150']]);$definition=DB::table('report_definitions')->where('slug','logistics-operations')->first();if(!$definition){$id=DB::table('report_definitions')->insertGetId(['uuid'=>(string)Str::uuid(),'user_id'=>$r->user()->id,'name'=>'Logistics Operations','slug'=>'logistics-operations','report_type'=>'logistics','status'=>'active','created_at'=>now(),'updated_at'=>now()]);$definition=DB::table('report_definitions')->find($id);}$id=DB::table('report_runs')->insertGetId(['uuid'=>(string)Str::uuid(),'report_definition_id'=>$definition->id,'user_id'=>$r->user()->id,'report_type'=>strtolower($d['operation_type']),'status'=>'queued','parameters'=>json_encode(['name'=>$d['name']]),'created_at'=>now(),'updated_at'=>now()]);activity('admin')->causedBy($r->user())->withProperties(['report_run_id'=>$id,'operation_type'=>$d['operation_type']])->log('logistics_report.created');return response()->json(['data'=>['operation'=>DB::table('report_runs')->find($id)]],201);}private function view($r){abort_unless($r->user()->hasPermission('logistics.view'),403);}private function create($r){abort_unless($r->user()->hasPermission('analytics.export'),403);}}
